files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;
  font-family: 'Open Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--vt-surface);
  color: var(--vt-ink-soft);
  overflow-x: hidden;
  padding-top: 94px;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  margin: 0;
  color: var(--vt-ink);
  font-weight: 600;
  line-height: 1.2;
}

.root p {
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
}

.root a {
  color: var(--vt-accent-ink);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.section {
  padding: 7rem 0;
}

.sectionTitle {
  text-align: center;
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 3rem;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
  padding: 20px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  display: inline-block;
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
}

.brand {
  color: inherit;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  margin-top: -74px;
}

.heroContainer {
  position: relative;
  height: 580px;
  overflow: hidden;
}

.heroSlider {
  position: absolute;
  inset: 0;
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.heroSlider::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.heroSubtitle {
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: color 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  text-align: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.aboutCol {
  flex: 1 1 100%;
  max-width: 100%;
}

.aboutTitle {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.aboutText {
  margin-bottom: 1rem;
}

.gallerySection {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryCol {
  flex: 0 0 50%;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  padding: 7rem 0 0;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: calc(100% - 60px);
  transform: translateX(-50%);
  z-index: 1;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  position: relative;
  margin-bottom: 3rem;
}

.timelineNode:last-child {
  margin-bottom: 0;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0.25rem;
  padding: 0;
  position: relative;
}

.timelineTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  font-size: 24px;
  font-weight: 600;
}

.timelineNode.odd .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineTitle::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineDesc,
.timelineDuration,
.timelinePrice {
  padding: 10px 30px;
}

.timelineDesc:last-child {
  padding-bottom: 30px;
}

.timelineIcon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.timelineNumber {
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
}

.timelineDate {
  padding: 1rem 0;
  color: var(--vt-ink-soft);
}

@media (min-width: 768px) {
  .timelineNode.odd {
    flex-direction: row;
  }
  .timelineNode.odd .timelineContent {
    flex: 0 0 50%;
    text-align: right;
    margin-right: auto;
  }
  .timelineNode.odd .timelineIcon {
    flex: 0 0 auto;
    margin: 0 1.5rem;
  }
  .timelineNode.odd .timelineDate {
    flex: 0 0 50%;
    text-align: left;
    margin-left: auto;
  }
  .timelineNode.even {
    flex-direction: row-reverse;
  }
  .timelineNode.even .timelineContent {
    flex: 0 0 50%;
    text-align: left;
    margin-left: auto;
  }
  .timelineNode.even .timelineIcon {
    flex: 0 0 auto;
    margin: 0 1.5rem;
  }
  .timelineNode.even .timelineDate {
    flex: 0 0 50%;
    text-align: right;
    margin-right: auto;
  }
}

@media (max-width: 767px) {
  .timeline::before {
    left: 33px;
    top: 60px;
    height: calc(100% - 60px);
    transform: none;
  }

  .timelineNode {
    flex-direction: row;
    align-items: flex-start;
    margin-left: 60px;
    position: relative;
  }

  .timelineIcon {
    position: absolute;
    left: -55px;
    top: 0;
    width: 70px;
    height: 70px;
    margin: 0;
  }

  .timelineContent {
    flex: 1;
    text-align: left;
    margin: 0;
  }

  .timelineDate {
    display: none;
  }

  .timelineNode.odd .timelineTitle::after,
  .timelineNode.even .timelineTitle::after {
    right: 100%;
    left: auto;
    border-right: 10px solid var(--vt-surface-deep);
    border-left: 0;
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }
}

.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerColHours,
.footerColClinic,
.footerColSocial {
  flex: 1 1 200px;
}

.footerColCopyright {
  flex: 1 1 100%;
  text-align: center;
  margin-top: 3rem;
}

.footerTitle {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 1.5rem;
}

.footerText {
  margin-bottom: 0.5rem;
}

.copyrightText {
  font-size: 16px;
}

@media screen and (min-width: 1600px) {
  .heroContainer {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .hero {
    margin-top: -54px;
  }

  .section {
    padding: 5rem 0;
  }

  .sectionTitle {
    font-size: 32px;
  }

  .nav {
    padding: 10px 0;
  }

  .heroTitle {
    font-size: 38px;
  }

  .aboutTitle {
    font-size: 32px;
  }

  .timelineTitle {
    font-size: 20px;
  }

  .footer {
    padding: 4rem 0;
  }
}

@media screen and (max-width: 767px) {
  .heroContainer {
    height: auto;
  }

  .heroSlider {
    position: relative;
    height: 300px;
  }

  .heroText {
    position: relative;
    width: auto;
    margin-bottom: 0;
    padding: 1.5rem;
  }

  .heroTitle {
    font-size: 32px;
  }

  .navLinks {
    gap: 1rem;
  }

  .navLinks a {
    font-size: 14px;
    padding: 10px 0;
  }

  .galleryCol {
    flex: 0 0 100%;
  }

  .timelineSection {
    padding: 5rem 0 0;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
    margin-right: 12px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .featured-number {
    font-size: 5rem;
  }

  .featured-circle {
    width: 235px;
    height: 235px;
  }

  .timeline::before {
    left: 42px;
  }
}
